+  if (rawArgs.includes("--help") || rawArgs.includes("-h")) {
+    console.log(USAGE);
     return;
   }
-  if (command === "create") {
-    if (!arg) throw new Error("Usage: vitadeck create <project-name>");
-    await create(arg);
+  if (rawArgs.includes("--version") || rawArgs.includes("-v")) {
